      case 29:
        return PickCase<Op, 29, EndIndex>::Run(std::forward<Op>(op));
      case 30:
        return PickCase<Op, 30, EndIndex>::Run(std::forward<Op>(op));
      case 31:
        return PickCase<Op, 31, EndIndex>::Run(std::forward<Op>(op));
      case 32:
