  friend auto operator<=>(const flat_tree& lhs, const flat_tree& rhs) {
    return lhs.body_ <=> rhs.body_;
  }

  friend void swap(flat_tree& lhs, flat_tree& rhs) noexcept { lhs.swap(rhs); }

 protected:


