bool AreAllUnique;
template <>
inline constexpr bool AreAllUnique<> = true;
template <typename T, typename... Ts>
inline constexpr bool AreAllUnique<T, Ts...> =
    (!std::is_same_v<T, Ts> && ...) && AreAllUnique<Ts...>;

